import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as t,o as i,af as s}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const u=JSON.parse('{"title":"MiniMax Code 实战 Cookbook","description":"只收官方步骤能覆盖的配方：Agent Team、自备 Key、headless、ACP、签到积分。","frontmatter":{"title":"MiniMax Code 实战 Cookbook","description":"只收官方步骤能覆盖的配方：Agent Team、自备 Key、headless、ACP、签到积分。","domain":"product","tags":["coding-agent"],"role":"cookbook"},"headers":[],"relativePath":"zh/products/minimax-code/minimax-code-cookbook.md","filePath":"zh/products/minimax-code/minimax-code-cookbook.md","lastUpdated":1787107158000}'),o={name:"zh/products/minimax-code/minimax-code-cookbook.md"};function n(d,e,r,l,c,p){return i(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="minimax-code-实战-cookbook" tabindex="-1">MiniMax Code 实战 Cookbook <a class="header-anchor" href="#minimax-code-实战-cookbook" aria-label="Permalink to &quot;MiniMax Code 实战 Cookbook&quot;">​</a></h1><p>跳着读。安装和第一次对话在 <a href="./minimax-code.html">教程</a>。这里只写「我要解决 X」。</p><h2 id="_1-让-agent-team-拆复杂任务" tabindex="-1">1. 让 Agent Team 拆复杂任务 <a class="header-anchor" href="#_1-让-agent-team-拆复杂任务" aria-label="Permalink to &quot;1. 让 Agent Team 拆复杂任务&quot;">​</a></h2><p>来源：<a href="https://agent.minimaxi.com/docs/code/agents/team" target="_blank" rel="noreferrer">Agent Team</a>。</p><p>官方：「Agent Team 会根据任务复杂度引入多个专家 Agent 协作。你仍然只需要描述目标，MiniMax Code 会负责拆解任务、分配执行、跟踪进度和汇总结果。」</p><p>适合：</p><ul><li>同时涉及代码、设计、文档、测试</li><li>需要长时间运行并持续跟进</li><li>需要分工执行和结果校验</li><li>需要多个方向并行探索</li></ul><p>写法：给出清晰目标、验收标准和限制条件。进行中可以继续补充信息；官方写 Agent Team 会把新要求纳入后续执行。</p><p>M3 博文补充过 Producer + Verifier 对抗循环和「可连续跑数天」的产品声明（<a href="https://www.minimax.io/blog/minimax-m3" target="_blank" rel="noreferrer">minimax-m3</a>）。具体排队策略、并发上限以产品内和 <a href="https://agent.minimaxi.com/docs/code/agents/team" target="_blank" rel="noreferrer">team</a> 为准，不要把博文修辞抄成操作保证。</p><p>简单单文件修改不必开 Team。</p><h2 id="_2-在-minimax-code-里用自己的-minimax-api-key" tabindex="-1">2. 在 MiniMax Code 里用自己的 MiniMax API Key <a class="header-anchor" href="#_2-在-minimax-code-里用自己的-minimax-api-key" aria-label="Permalink to &quot;2. 在 MiniMax Code 里用自己的 MiniMax API Key&quot;">​</a></h2><p>来源：<a href="https://agent.minimaxi.com/docs/code/account/minimax-api" target="_blank" rel="noreferrer">MiniMax API Key</a>。</p><ol><li>进入用量与模型相关设置。</li><li>选择 MiniMax API，输入 API Key 并保存。</li><li>使用连接测试确认 Key 可用。</li></ol><p>官方 Warning：「不要把 API Key 写进对话正文、代码仓库或公开文档。请只通过产品内的安全配置入口保存。」</p><p>CLI 侧用 <code>mcode provider</code>，或 <code>mcode provider --help</code> 看命令行配置（<a href="https://agent.minimaxi.com/docs/cli/faq" target="_blank" rel="noreferrer">CLI FAQ</a>）。</p><p>自定义供应商（Base URL、API Format、模型名）走 <a href="https://agent.minimaxi.com/docs/code/account/byok" target="_blank" rel="noreferrer">BYOK</a>，不要和 MiniMax 官方 Key 混成同一步。</p><h2 id="_3-用-cli-跑一次-headless-任务" tabindex="-1">3. 用 CLI 跑一次 Headless 任务 <a class="header-anchor" href="#_3-用-cli-跑一次-headless-任务" aria-label="Permalink to &quot;3. 用 CLI 跑一次 Headless 任务&quot;">​</a></h2><p>来源：<a href="https://agent.minimaxi.com/docs/cli/features" target="_blank" rel="noreferrer">功能介绍</a>。</p><p><code>mcode exec</code> 不启动 TUI。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;修复失败的测试&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --cwd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./repo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> error.log</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --output-format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;分析错误日志，修复问题并运行相关测试&quot;</span></span></code></pre></div><p>官方参数：</p><table tabindex="0"><thead><tr><th>参数</th><th>用途</th></tr></thead><tbody><tr><td><code>--cwd</code></td><td>指定工作区目录</td></tr><tr><td><code>--file</code></td><td>添加附件，可重复</td></tr><tr><td><code>--model</code></td><td>仅本次指定模型</td></tr><tr><td><code>--session</code> / <code>--continue</code></td><td>在已有 Session 中跑</td></tr><tr><td><code>--permission</code></td><td><code>ask</code>、<code>smart</code>、<code>full</code> 或 <code>off</code></td></tr><tr><td><code>--timeout</code></td><td>如 <code>30s</code>、<code>2m</code></td></tr><tr><td><code>--max-steps</code></td><td>限制 Assistant 步数</td></tr><tr><td><code>--output-format</code></td><td><code>text</code>、<code>json</code> 或 <code>stream-json</code></td></tr><tr><td><code>--output-schema</code></td><td>用 JSON Schema 校验最终 JSON</td></tr></tbody></table><p>机器输出写 <code>stdout</code>，诊断写 <code>stderr</code>。只有显式 <code>--input -</code> 时才读标准输入，避免 CI 空等。</p><h2 id="_4-把-mcode-接到-zed-acp" tabindex="-1">4. 把 <code>mcode</code> 接到 Zed（ACP） <a class="header-anchor" href="#_4-把-mcode-接到-zed-acp" aria-label="Permalink to &quot;4. 把 \`mcode\` 接到 Zed（ACP）&quot;">​</a></h2><p>来源：<a href="https://agent.minimaxi.com/docs/cli/features" target="_blank" rel="noreferrer">功能介绍</a>。</p><p><code>mcode acp</code> 作为 ACP v1 Agent server，经 <code>stdin/stdout</code> 传 NDJSON。官方说不需要额外 HTTP 服务，也不要求编辑器安装 MCode 专用插件。</p><p>Zed External Agents 示例（官方原文）：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;agent_servers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;minimax-code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;custom&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mcode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;acp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;env&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>编辑器找不到命令时，把 <code>command</code> 改成 <code>mcode</code> 的绝对路径。官方约束：<code>mcode acp</code> 的 <code>stdout</code> 只用于协议消息，不要直接往里打自然语言，也不要让包装脚本把日志写进 <code>stdout</code>。</p><p>其它 ACP 宿主没有官方逐步截图时，不要编「官方 VS Code 插件」。</p><h2 id="_5-看用量和签到积分" tabindex="-1">5. 看用量和签到积分 <a class="header-anchor" href="#_5-看用量和签到积分" aria-label="Permalink to &quot;5. 看用量和签到积分&quot;">​</a></h2><p>来源：<a href="https://agent.minimaxi.com/docs/code/account/usage" target="_blank" rel="noreferrer">Token Plan 与积分</a>。</p><p>设置的用量页可看：当前订阅、Token Plan 有效期、积分余额、用量额度、订阅 / 充值 / 发票 / 签到入口。</p><p>官方签到数字（同一页）：</p><ul><li>每日签到 <strong>400 积分</strong></li><li>连续第 4 天、第 7 天单日 <strong>1000 积分</strong></li><li>完成一周累计 <strong>4000 积分</strong></li><li>自到账之日起 <strong>30 天内</strong>有效</li></ul><p>同一页最后一句：「具体计费和额度规则以产品内展示为准。」</p><p>下载页上的 Plus / Max / Ultra 月费和开放平台 Token Plan 美元档<strong>不是同一张表</strong>。不要在配方里合并报价。见 <a href="./minimax-code-cheatsheet.html">速查表</a>。</p><h2 id="_6-定时任务不跑时先查这三件事" tabindex="-1">6. 定时任务不跑时先查这三件事 <a class="header-anchor" href="#_6-定时任务不跑时先查这三件事" aria-label="Permalink to &quot;6. 定时任务不跑时先查这三件事&quot;">​</a></h2><p>来源：<a href="https://agent.minimaxi.com/docs/code/help/faq" target="_blank" rel="noreferrer">桌面 FAQ</a>。</p><p>「请确认电脑处于唤醒状态、MiniMax Code 正在运行，并且任务处于启用状态。」</p><p>CLI 没有桌面那套定时任务宿主。FAQ 原文：Browser、Computer Use「只有在当前宿主明确提供时才会出现；不能仅因为桌面端支持就假定 CLI 环境也支持。」</p><h2 id="_7-常见安装翻车" tabindex="-1">7. 常见安装翻车 <a class="header-anchor" href="#_7-常见安装翻车" aria-label="Permalink to &quot;7. 常见安装翻车&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>官方处理</th></tr></thead><tbody><tr><td><code>mcode: command not found</code></td><td>重开终端；查 <code>PATH</code>；VS Code 要整进程退出（<a href="https://agent.minimaxi.com/docs/cli/faq" target="_blank" rel="noreferrer">CLI FAQ</a>）</td></tr><tr><td>安装失败</td><td>确认能访问 MiniMax 文件 CDN、Node.js 官网、npm registry；原生依赖还可能访问 GitHub。代理先设 <code>HTTP_PROXY</code> / <code>HTTPS_PROXY</code> / <code>ALL_PROXY</code> / <code>NO_PROXY</code></td></tr><tr><td>Alpine / musl</td><td>官方暂不支持</td></tr><tr><td>Windows 桌面装不上</td><td>查系统版本、安装路径权限、企业代理（<a href="https://agent.minimaxi.com/docs/code/get-started/download" target="_blank" rel="noreferrer">download</a>）</td></tr><tr><td>自定义模型连不上</td><td>查 Base URL、API Key、模型名、网络、API Format（<a href="https://agent.minimaxi.com/docs/code/help/faq" target="_blank" rel="noreferrer">桌面 FAQ</a>）</td></tr></tbody></table><p>把 MiniMax-M3 接到 Claude Code / Cursor 的步骤在 <a href="https://platform.minimaxi.com/docs/guides/text-ai-coding-tools" target="_blank" rel="noreferrer">text-ai-coding-tools</a>，不要写进本页当 MiniMax Code 配方。</p>`,44)])])}const C=a(o,[["render",n]]);export{u as __pageData,C as default};
